// Everything here runs against an httptest fake of the GitHub API and a key generated by the test.
// No test reads a real key or calls api.github.com.

var (
	testKeyOnce sync.Once
	testKey     *rsa.PrivateKey
)

func genKey(t *testing.T) *rsa.PrivateKey {
	t.Helper()
	testKeyOnce.Do(func() {
		k, err := rsa.GenerateKey(rand.Reader, 2048)
		if err != nil {
			panic(err)
		}
		testKey = k
	})
	return testKey
}

func keyPEM(t *testing.T) []byte {
	return pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(genKey(t))})
}

// fakeGitHub answers the two calls the helper makes and records them.
type fakeGitHub struct {
	t   *testing.T
	srv *httptest.Server

	mu            sync.Mutex
	tokenCalls    int
	lookupCalls   int
	bodies        []string
	jwts          []string
	installations []int64
	tokenFor      func(n int) string // the token the nth call returns
	lifetime      time.Duration      // expires_at = now + lifetime
	grantExtra    map[string]string  // permissions added to the answer
	grantAll      bool               // answer repository_selection all: no repositories
	account       string             // the account the installations belong to ("" is the organization)
	repoOwner     string             // the owner of the repositories in the token answer ("" is the organization)
	status        int                // non-zero: answer this status with a body that echoes the request
	redirectTo    string
}

func newFake(t *testing.T) *fakeGitHub {
	f := &fakeGitHub{t: t, installations: []int64{77}, lifetime: time.Hour, tokenFor: func(n int) string { return fmt.Sprintf("ghs_fake%d", n) }}
	f.srv = httptest.NewServer(http.HandlerFunc(f.handle))
	t.Cleanup(f.srv.Close)
	return f
}

func (f *fakeGitHub) handle(w http.ResponseWriter, r *http.Request) {
	f.mu.Lock()
	defer f.mu.Unlock()
	auth := r.Header.Get("Authorization")
	f.jwts = append(f.jwts, strings.TrimPrefix(auth, "Bearer "))
	if f.redirectTo != "" {
		http.Redirect(w, r, f.redirectTo, http.StatusFound)
		return
	}
	if f.status != 0 {
		w.WriteHeader(f.status)
		fmt.Fprintf(w, `{"message":"no","echo":%q}`, auth)
		return
	}
	switch {
	case r.Method == http.MethodGet && r.URL.Path == "/app/installations":
		f.lookupCalls++
		var out []map[string]any
		for _, id := range f.installations {
			acct := f.account
			if acct == "" {
				acct = appOwner
			}
			out = append(out, map[string]any{"id": id, "account": map[string]any{"login": acct}})
		}
		json.NewEncoder(w).Encode(out)
	case r.Method == http.MethodPost && strings.HasPrefix(r.URL.Path, "/app/installations/") && strings.HasSuffix(r.URL.Path, "/access_tokens"):
		f.tokenCalls++
		var body struct {
			Repositories []string          `json:"repositories"`
			Permissions  map[string]string `json:"permissions"`
		}
		raw := new(bytes.Buffer)
		raw.ReadFrom(r.Body)
		f.bodies = append(f.bodies, strings.TrimSpace(raw.String()))
		json.Unmarshal(raw.Bytes(), &body)
		perms := map[string]string{"metadata": "read"}
		for k, v := range body.Permissions {
			perms[k] = v
		}
		for k, v := range f.grantExtra {
			perms[k] = v
		}
		ans := map[string]any{"token": f.tokenFor(f.tokenCalls), "expires_at": time.Now().Add(f.lifetime).UTC().Format(time.RFC3339), "permissions": perms}
		if !f.grantAll {
			var repos []map[string]any
			for _, n := range body.Repositories {
				owner := f.repoOwner
				if owner == "" {
					owner = appOwner
				}
				repos = append(repos, map[string]any{"name": n, "full_name": owner + "/" + n})
			}
			ans["repositories"] = repos
		}
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(ans)
	default:
		http.NotFound(w, r)
	}
}

func (f *fakeGitHub) calls() (token, lookup int) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.tokenCalls, f.lookupCalls
}

// rig is a key folder in the right modes, a fake API and a clock the test moves.
type rig struct {
	t    *testing.T
	fake *fakeGitHub
	a    *app
	dir  string
	now  time.Time
}

func newRig(t *testing.T) *rig {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "coral-agents")
	if err := os.Mkdir(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(dir, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, keyFileName), keyPEM(t), 0o600); err != nil {
		t.Fatal(err)
	}
	r := &rig{t: t, fake: newFake(t), dir: dir, now: time.Now()}
	r.a = &app{base: r.fake.srv.URL, keys: keyStore{dir: dir, uid: os.Getuid()}, now: func() time.Time { return r.now }}
	return r
}

func (r *rig) run(args ...string) (code int, stdout, stderr string) {
	return r.runIn("", args...)
}

func (r *rig) runIn(stdin string, args ...string) (code int, stdout, stderr string) {
	var out, errb bytes.Buffer
	code = run(args, strings.NewReader(stdin), &out, &errb, r.a)
	return code, out.String(), errb.String()
}

func (r *rig) keyFile() string { return filepath.Join(r.dir, keyFileName) }

// ---- the permission set is narrowed, and an unknown set is refused ----

func TestThePermissionSetIsNarrowedAndTheTokenLimitedToOneRepository(t *testing.T) {
	cases := []struct {
		perms, repo, body string
	}{
		{"push", "coral", `{"repositories":["coral"],"permissions":{"contents":"write","pull_requests":"write"}}`},
		{"dispatch", "coral", `{"repositories":["coral"],"permissions":{"actions":"write"}}`},
		{"push", "homebrew-coral", `{"repositories":["homebrew-coral"],"permissions":{"contents":"write","pull_requests":"write"}}`},
	}
	for _, c := range cases {
		r := newRig(t)
		code, out, errs := r.run("--perms", c.perms, "--repo", c.repo, "--installation-id", "77", "token")
		if code != 0 || out != "ghs_fake1\n" || errs != "" {
			t.Fatalf("%v: code=%d out=%q err=%q", c, code, out, errs)
		}
		if len(r.fake.bodies) != 1 || r.fake.bodies[0] != c.body {
			t.Fatalf("%v: body %q, want %q", c, r.fake.bodies, c.body)
		}
	}
}

func TestAnUnknownPermissionSetOrRepositoryIsRefusedWithoutAnyRequest(t *testing.T) {
	r := newRig(t)
	for _, perms := range []string{"", "admin", "PUSH", "push,dispatch", "contents:write", "actions:write", "all", "push ", "workflows"} {
		code, out, _ := r.run("--perms", perms, "--installation-id", "77", "token")
		if code == 0 || out != "" {
			t.Fatalf("perms %q: code=%d out=%q", perms, code, out)
		}
	}
	for _, repo := range []string{"", "other", "coral,homebrew-coral", "subgentic/coral", "Coral", "*"} {
		code, out, _ := r.run("--perms", "push", "--repo", repo, "--installation-id", "77", "token")
		if code == 0 || out != "" {
			t.Fatalf("repo %q: code=%d out=%q", repo, code, out)
		}
	}
	if code, _, _ := r.run("--perms", "push", "--installation-id", "-3", "token"); code == 0 {
		t.Fatal("a negative installation id was accepted")
	}
	if tok, look := r.fake.calls(); tok != 0 || look != 0 {
		t.Fatalf("refused requests still reached GitHub: %d token calls, %d lookups", tok, look)
	}
}

