// A token wider than asked for, or not limited to the repository, is refused and not cached.
func TestAWiderTokenThanAskedForIsRefusedAndNotCached(t *testing.T) {
	for name, tweak := range map[string]func(*fakeGitHub){
		"extra permission":    func(f *fakeGitHub) { f.grantExtra = map[string]string{"administration": "write"} },
		"upgraded permission": func(f *fakeGitHub) { f.grantExtra = map[string]string{"contents": "admin"} },
		"all repositories":    func(f *fakeGitHub) { f.grantAll = true },
		"another owner":       func(f *fakeGitHub) { f.repoOwner = "someone-else" }, // the repository name matches, the account does not (#5528 review)
	} {
		r := newRig(t)
		tweak(r.fake)
		code, out, errs := r.run("--perms", "push", "--installation-id", "77", "token")
		if code == 0 || out != "" || !strings.Contains(errs, "refused") {
			t.Fatalf("%s: code=%d out=%q err=%q", name, code, out, errs)
		}
		if strings.Contains(errs, "ghs_") {
			t.Fatalf("%s: the refused token leaked into the error: %q", name, errs)
		}
		if _, err := os.Stat(filepath.Join(r.dir, "cache")); err == nil {
			entries, _ := os.ReadDir(filepath.Join(r.dir, "cache"))
			if len(entries) != 0 {
				t.Fatalf("%s: a refused token was cached", name)
			}
		}
	}
}

// ---- the JWT ----

func TestTheJWTIsRS256IssuedASixtySecondsBackAndValidNineMinutes(t *testing.T) {
	r := newRig(t)
	if code, _, errs := r.run("--perms", "push", "--installation-id", "77", "token"); code != 0 {
		t.Fatal(errs)
	}
	var claims jwt.RegisteredClaims
	tok, err := jwt.ParseWithClaims(r.fake.jwts[0], &claims, func(*jwt.Token) (any, error) { return &genKey(t).PublicKey, nil },
		jwt.WithValidMethods([]string{"RS256"}), jwt.WithoutClaimsValidation())
	if err != nil || !tok.Valid {
		t.Fatalf("the JWT does not verify with the test key: %v", err)
	}
	if claims.Issuer != "5405319" {
		t.Fatalf("issuer %q", claims.Issuer)
	}
	iat, exp := claims.IssuedAt.Time, claims.ExpiresAt.Time
	if d := r.now.Sub(iat); d < 59*time.Second || d > 62*time.Second {
		t.Fatalf("issued %v before now, want 60s", d)
	}
	if d := exp.Sub(r.now); d < 8*time.Minute+58*time.Second || d > 9*time.Minute+2*time.Second {
		t.Fatalf("expires %v after now, want 9 minutes", d)
	}
}

// ---- the key path and modes ----

func TestTheKeyFileMustBeExactly0600(t *testing.T) {
	for _, mode := range []os.FileMode{0o644, 0o640, 0o660, 0o666, 0o400, 0o700, 0o604} {
		r := newRig(t)
		if err := os.Chmod(r.keyFile(), mode); err != nil {
			t.Fatal(err)
		}
		code, out, errs := r.run("--perms", "push", "--installation-id", "77", "token")
		if code == 0 || out != "" || !strings.Contains(errs, "0600") {
			t.Fatalf("mode %04o: code=%d out=%q err=%q", mode, code, out, errs)
		}
		if tok, _ := r.fake.calls(); tok != 0 {
			t.Fatalf("mode %04o: GitHub was called", mode)
		}
	}
}

func TestTheKeyFolderMustBeExactly0700(t *testing.T) {
	for _, mode := range []os.FileMode{0o755, 0o750, 0o770, 0o777, 0o500, 0o701} {
		r := newRig(t)
		if err := os.Chmod(r.dir, mode); err != nil {
			t.Fatal(err)
		}
		code, out, errs := r.run("--perms", "push", "--installation-id", "77", "token")
		os.Chmod(r.dir, 0o700)
		if code == 0 || out != "" || !strings.Contains(errs, "0700") {
			t.Fatalf("mode %04o: code=%d out=%q err=%q", mode, code, out, errs)
		}
	}
}

func TestASymlinkedKeyFileIsRefusedEvenToAGoodKey(t *testing.T) {
	r := newRig(t)
	real := filepath.Join(t.TempDir(), "real.pem")
	if err := os.WriteFile(real, keyPEM(t), 0o600); err != nil {
		t.Fatal(err)
	}
	os.Remove(r.keyFile())
	if err := os.Symlink(real, r.keyFile()); err != nil {
		t.Fatal(err)
	}
	code, out, errs := r.run("--perms", "push", "--installation-id", "77", "token")
	if code == 0 || out != "" || !strings.Contains(errs, "symlink") {
		t.Fatalf("code=%d out=%q err=%q", code, out, errs)
	}
}

func TestASymlinkedKeyFolderIsRefused(t *testing.T) {
	r := newRig(t)
	link := filepath.Join(t.TempDir(), "link")
	if err := os.Symlink(r.dir, link); err != nil {
		t.Fatal(err)
	}
	r.a.keys.dir = link
	code, out, errs := r.run("--perms", "push", "--installation-id", "77", "token")
	if code == 0 || out != "" || !strings.Contains(errs, "symlink") {
		t.Fatalf("code=%d out=%q err=%q", code, out, errs)
	}
}

func TestAKeyFileOwnedBySomeoneElseIsRefused(t *testing.T) {
	r := newRig(t)
	r.a.keys.uid = os.Getuid() + 1
	code, out, errs := r.run("--perms", "push", "--installation-id", "77", "token")
	if code == 0 || out != "" || !strings.Contains(errs, "not owned by this user") {
		t.Fatalf("code=%d out=%q err=%q", code, out, errs)
	}
}

func TestAKeyThatIsMissingADirectoryOrTooBigIsRefused(t *testing.T) {
	r := newRig(t)
	os.Remove(r.keyFile())
	if code, _, _ := r.run("--perms", "push", "--installation-id", "77", "token"); code == 0 {
		t.Fatal("a missing key was accepted")
	}
	if err := os.Mkdir(r.keyFile(), 0o700); err != nil {
		t.Fatal(err)
	}
	if code, _, errs := r.run("--perms", "push", "--installation-id", "77", "token"); code == 0 || !strings.Contains(errs, "0600") && !strings.Contains(errs, "regular") {
		t.Fatalf("a directory in the key's place: code=%d err=%q", code, errs)
	}
	os.Remove(r.keyFile())
	if err := os.WriteFile(r.keyFile(), bytes.Repeat([]byte("A"), maxKeyBytes+1), 0o600); err != nil {
		t.Fatal(err)
	}
	if code, _, errs := r.run("--perms", "push", "--installation-id", "77", "token"); code == 0 || !strings.Contains(errs, "larger") {
		t.Fatalf("an oversized key: code=%d err=%q", code, errs)
	}
}

func TestANonKeyFileIsRefusedWithoutEchoingItsContent(t *testing.T) {
	r := newRig(t)
	secret := "not-a-key-but-secret-looking-text-0123456789"
	os.WriteFile(r.keyFile(), []byte(secret), 0o600)
	code, out, errs := r.run("--perms", "push", "--installation-id", "77", "token")
	if code == 0 || out != "" || strings.Contains(errs, secret) {
		t.Fatalf("code=%d out=%q err=%q", code, out, errs)
	}
}

// The key comes from the one file: no flag, variable or input names another source.
func TestTheKeyIsNeverTakenFromAFlagOrAnEnvironmentVariable(t *testing.T) {
	r := newRig(t)
	for _, flagName := range []string{"--key", "--private-key", "--key-file", "--pem", "--base-url", "--api-url"} {
		code, out, _ := r.run(flagName, "x", "--perms", "push", "--installation-id", "77", "token")
		if code == 0 || out != "" {
			t.Fatalf("%s was accepted", flagName)
		}
	}
	os.Remove(r.keyFile())
	for _, name := range []string{"CORAL_AGENTS_KEY", "GITHUB_APP_PRIVATE_KEY", "PRIVATE_KEY", "CORAL_AGENTS_PRIVATE_KEY"} {
		t.Setenv(name, string(keyPEM(t)))
	}
	if code, out, _ := r.runIn(string(keyPEM(t)), "--perms", "push", "--installation-id", "77", "token"); code == 0 || out != "" {
		t.Fatal("a key from the environment or from standard input was used")
	}
	if tok, _ := r.fake.calls(); tok != 0 {
		t.Fatal("GitHub was called without a key file")
	}
}

// ---- the cache ----

func TestTheTokenIsCachedForFiftyMinutesAndThenFetchedAgain(t *testing.T) {
	r := newRig(t)
	args := []string{"--perms", "push", "--installation-id", "77", "token"}
	_, first, _ := r.run(args...)
	r.now = r.now.Add(49 * time.Minute)
	_, second, _ := r.run(args...)
	if first != "ghs_fake1\n" || second != first {
		t.Fatalf("within 50 minutes: %q then %q", first, second)
	}
	if tok, _ := r.fake.calls(); tok != 1 {
		t.Fatalf("%d token calls inside 50 minutes, want 1", tok)
	}
	r.now = r.now.Add(2 * time.Minute) // 51 minutes after the fetch
	_, third, _ := r.run(args...)
	if third != "ghs_fake2\n" {
		t.Fatalf("after 50 minutes: %q", third)
	}
	if tok, _ := r.fake.calls(); tok != 2 {
		t.Fatalf("%d token calls after 51 minutes, want 2", tok)
	}
}

// A token GitHub says dies sooner than 50 minutes is not served up to its last minutes.
func TestACachedTokenIsNotServedNearTheExpiryGitHubStates(t *testing.T) {
	r := newRig(t)
	r.fake.lifetime = 20 * time.Minute
	args := []string{"--perms", "push", "--installation-id", "77", "token"}
	r.run(args...)
	r.now = r.now.Add(17 * time.Minute)
	r.run(args...)
	if tok, _ := r.fake.calls(); tok != 1 {
		t.Fatalf("%d calls at 17 of 20 minutes, want 1", tok)
	}
	r.now = r.now.Add(2 * time.Minute) // within the 2-minute margin of the 20
	r.run(args...)
	if tok, _ := r.fake.calls(); tok != 2 {
		t.Fatalf("%d calls inside the margin, want 2", tok)
	}
}

func TestTheCacheIsA0600FileInsideA0700Folder(t *testing.T) {
	r := newRig(t)
	r.run("--perms", "push", "--installation-id", "77", "token")
	dir := filepath.Join(r.dir, "cache")
	di, err := os.Stat(dir)
	if err != nil || di.Mode().Perm() != 0o700 {
		t.Fatalf("cache folder: %v %v", di, err)
	}
	entries, _ := os.ReadDir(dir)
	if len(entries) != 1 {
		t.Fatalf("%d files in the cache, want 1 (no temp file left)", len(entries))
	}
	fi, _ := entries[0].Info()
	if fi.Mode().Perm() != 0o600 {
		t.Fatalf("cache file mode %04o", fi.Mode().Perm())
	}
}

// Each (permission set, repository, installation) has its own entry: a push token is never served for a dispatch.
func TestACachedTokenIsNeverServedForAnotherSetRepositoryOrInstallation(t *testing.T) {
	r := newRig(t)
	r.run("--perms", "push", "--installation-id", "77", "token")
	for _, args := range [][]string{
		{"--perms", "dispatch", "--installation-id", "77", "token"},
		{"--perms", "push", "--repo", "homebrew-coral", "--installation-id", "77", "token"},
		{"--perms", "push", "--installation-id", "78", "token"},
	} {
		before, _ := r.fake.calls()
		r.run(args...)
		after, _ := r.fake.calls()
		if after != before+1 {
			t.Fatalf("%v was served from the cache", args)
		}
	}
	if len(r.fake.bodies) != 4 || !strings.Contains(r.fake.bodies[1], `"actions":"write"`) || strings.Contains(r.fake.bodies[1], "contents") {
		t.Fatalf("bodies %q", r.fake.bodies)
	}
}

// A cache file anyone could read, a link, or garbage is a miss that is replaced, never a token served.
func TestAWorldReadableLinkedOrBrokenCacheFileIsIgnoredAndReplaced(t *testing.T) {
	args := []string{"--perms", "push", "--installation-id", "77", "token"}
	file := func(r *rig) string { return filepath.Join(r.dir, "cache", "77-coral-push.json") }
	for name, damage := range map[string]func(r *rig){
		"mode 0644": func(r *rig) { os.Chmod(file(r), 0o644) },
		"symlink": func(r *rig) {
			b, _ := os.ReadFile(file(r))
			target := filepath.Join(t.TempDir(), "elsewhere.json")
			os.WriteFile(target, b, 0o600)
			os.Remove(file(r))
			os.Symlink(target, file(r))
		},
		"garbage":      func(r *rig) { os.WriteFile(file(r), []byte("{not json"), 0o600) },
		"empty token":  func(r *rig) { os.WriteFile(file(r), []byte(`{"token":"","repo":"coral","perms":"push"}`), 0o600) },
		"future fetch": func(r *rig) { r.now = r.now.Add(-time.Hour) },
		"folder 0755":  func(r *rig) { os.Chmod(filepath.Join(r.dir, "cache"), 0o755) },
		"other repo": func(r *rig) {
			os.WriteFile(file(r), []byte(fmt.Sprintf(`{"token":"ghs_planted","expires_at":%q,"fetched_at":%q,"installation_id":77,"repo":"homebrew-coral","perms":"push"}`, r.now.Add(time.Hour).Format(time.RFC3339), r.now.Format(time.RFC3339))), 0o600)
		},
		"other installation": func(r *rig) {
			os.WriteFile(file(r), []byte(fmt.Sprintf(`{"token":"ghs_planted","expires_at":%q,"fetched_at":%q,"installation_id":99,"repo":"coral","perms":"push"}`, r.now.Add(time.Hour).Format(time.RFC3339), r.now.Format(time.RFC3339))), 0o600)
		},
		"other perms": func(r *rig) {
			os.WriteFile(file(r), []byte(fmt.Sprintf(`{"token":"ghs_planted","expires_at":%q,"fetched_at":%q,"installation_id":77,"repo":"coral","perms":"dispatch"}`, r.now.Add(time.Hour).Format(time.RFC3339), r.now.Format(time.RFC3339))), 0o600)
		},
	} {
		r := newRig(t)
		r.run(args...)
		damage(r)
		code, out, _ := r.run(args...)
		os.Chmod(filepath.Join(r.dir, "cache"), 0o700)
		if name == "folder 0755" {
			// the whole run is refused until the folder is put right: the folder rule covers the cache too
			if code == 0 || out != "" {
				t.Fatalf("%s: a cache folder of mode 0755 was used (code=%d out=%q)", name, code, out)
			}
			continue
		}
		if code != 0 || out != "ghs_fake2\n" {
			t.Fatalf("%s: code=%d out=%q, want a fresh token", name, code, out)
		}
		if tok, _ := r.fake.calls(); tok != 2 {
			t.Fatalf("%s: %d token calls, want 2", name, tok)
		}
		if fi, err := os.Lstat(file(r)); err != nil || fi.Mode().Perm() != 0o600 || fi.Mode()&os.ModeSymlink != 0 {
			t.Fatalf("%s: the replaced cache file is %v %v", name, fi, err)
		}
	}
}

// The cache folder's mode is checked even when the key folder alone would pass: a cache of 0755 stops the run.
func TestTheKeyFolderRuleAppliesToACachedRunToo(t *testing.T) {
	r := newRig(t)
	args := []string{"--perms", "push", "--installation-id", "77", "token"}
	r.run(args...)
	os.Chmod(r.dir, 0o755)
	defer os.Chmod(r.dir, 0o700)
	code, out, _ := r.run(args...)
	if code == 0 || out != "" {
		t.Fatalf("a cached token was served from a folder of mode 0755 (code=%d)", code)
	}
}

// ---- the installation lookup ----

func TestWithoutAnInstallationIdTheOnlyInstallationIsLookedUpAndItsTokenCached(t *testing.T) {
	r := newRig(t)
	r.fake.installations = []int64{4242}
	args := []string{"--perms", "push", "token"}
	_, out, errs := r.run(args...)
	if out != "ghs_fake1\n" || errs != "" {
		t.Fatalf("out=%q err=%q", out, errs)
	}
	r.run(args...)
	tok, look := r.fake.calls()
	if tok != 1 || look != 1 {
		t.Fatalf("%d token calls and %d lookups for two runs, want 1 and 1 (the second is cached)", tok, look)
	}
}

func TestTheLookupRefusesNoInstallationAndSeveral(t *testing.T) {
	for name, ids := range map[string][]int64{"none": nil, "two": {1, 2}} {
		r := newRig(t)
		r.fake.installations = ids
		code, out, errs := r.run("--perms", "push", "token")
		if code == 0 || out != "" || errs == "" {
			t.Fatalf("%s: code=%d out=%q err=%q", name, code, out, errs)
		}
		if tok, _ := r.fake.calls(); tok != 0 {
			t.Fatalf("%s: a token was requested without a single installation", name)
		}
	}
}

// ---- secrets stay out of everything but standard output ----

func TestNoSecretReachesStderrOrAFailureOutput(t *testing.T) {
	for _, status := range []int{http.StatusUnauthorized, http.StatusForbidden, http.StatusNotFound, http.StatusInternalServerError} {
		r := newRig(t)
		r.fake.status = status
		code, out, errs := r.run("--perms", "push", "--installation-id", "77", "token")
		if code == 0 || out != "" {
			t.Fatalf("%d: code=%d out=%q", status, code, out)
		}
		all := errs + out
		for _, secret := range []string{"BEGIN", "PRIVATE KEY", "Bearer", "eyJ", "ghs_"} {
			if strings.Contains(all, secret) {
				t.Fatalf("%d: %q leaked: %q", status, secret, all)
			}
		}
		if !strings.Contains(errs, fmt.Sprint(status)) {
			t.Fatalf("%d: the status is not named: %q", status, errs)
		}
	}
	// the lookup path too
	r := newRig(t)
	r.fake.status = http.StatusUnauthorized
	_, out, errs := r.run("--perms", "push", "token")
	for _, secret := range []string{"BEGIN", "Bearer", "eyJ"} {
		if strings.Contains(errs+out, secret) {
			t.Fatalf("lookup: %q leaked: %q", secret, errs+out)
		}
	}
}

func TestOnSuccessTheTokenIsOnStdoutAloneAndStderrIsEmpty(t *testing.T) {
	r := newRig(t)
	code, out, errs := r.run("--perms", "dispatch", "--installation-id", "77", "token")
	if code != 0 || out != "ghs_fake1\n" || errs != "" {
		t.Fatalf("code=%d out=%q err=%q", code, out, errs)
	}
	// and the key is never written anywhere in the cache
	filepath.Walk(filepath.Join(r.dir, "cache"), func(p string, fi os.FileInfo, _ error) error {
		if fi != nil && fi.Mode().IsRegular() {
			b, _ := os.ReadFile(p)
			if bytes.Contains(b, []byte("PRIVATE KEY")) || bytes.Contains(b, []byte("eyJ")) {
				t.Errorf("%s holds key or JWT material", p)
			}
		}
		return nil
	})
}

// The JWT and the token go to the API host and nowhere else: a redirect is not followed.
func TestARedirectIsNotFollowed(t *testing.T) {
	var hit bool
	other := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) { hit = true }))
	defer other.Close()
	r := newRig(t)
	r.fake.redirectTo = other.URL + "/steal"
	code, out, _ := r.run("--perms", "push", "--installation-id", "77", "token")
	code2, out2, _ := r.run("--perms", "push", "token")
	if code == 0 || code2 == 0 || out != "" || out2 != "" || hit {
		t.Fatalf("a redirect was followed or answered: %d %d %q %q hit=%v", code, code2, out, out2, hit)
	}
}

// ---- git credential helper ----

const gitGet = "protocol=https\nhost=github.com\n\n"

func TestTheCredentialHelperAnswersGetForGitHubOverHTTPS(t *testing.T) {
	r := newRig(t)
	code, out, errs := r.runIn(gitGet, "--perms", "push", "--installation-id", "77", "credential", "get")
	if code != 0 || errs != "" {
		t.Fatalf("code=%d err=%q", code, errs)
	}
	lines := strings.Split(strings.TrimSuffix(out, "\n\n"), "\n")
	if len(lines) != 3 || lines[0] != "username=x-access-token" || lines[1] != "password=ghs_fake1" || !strings.HasPrefix(lines[2], "password_expiry_utc=") {
		t.Fatalf("answer %q", out)
	}
	if !strings.HasSuffix(out, "\n\n") {
		t.Fatalf("the answer must end with a blank line: %q", out)
	}
	// the expiry git is told is the cache's, not GitHub's hour
	if want := fmt.Sprintf("password_expiry_utc=%d", r.now.Add(cacheMaxAge).Unix()); lines[2] != want {
		t.Fatalf("expiry %q, want %q", lines[2], want)
	}
}

func TestTheCredentialHelperStaysSilentForAnyOtherHostProtocolOrRepository(t *testing.T) {
	r := newRig(t)
	for name, in := range map[string]string{
		"http":         "protocol=http\nhost=github.com\n\n",
		"other host":   "protocol=https\nhost=gist.github.com\n\n",
		"look-alike":   "protocol=https\nhost=github.com.evil.example\n\n",
		"port":         "protocol=https\nhost=github.com:8443\n\n",
		"ssh":          "protocol=ssh\nhost=github.com\n\n",
		"no host":      "protocol=https\n\n",
		"empty":        "",
		"other repo":   "protocol=https\nhost=github.com\npath=subgentic/other.git\n\n",
		"another repo": "protocol=https\nhost=github.com\npath=subgentic/homebrew-coral.git\n\n",
	} {
		code, out, errs := r.runIn(in, "--perms", "push", "--installation-id", "77", "credential", "get")
		if code != 0 || out != "" || errs != "" {
			t.Fatalf("%s: code=%d out=%q err=%q", name, code, out, errs)
		}
	}
	if code, out, _ := r.runIn("protocol=https\nhost=github.com\npath=subgentic/coral.git\n\n", "--perms", "push", "--installation-id", "77", "credential", "get"); code != 0 || !strings.Contains(out, "password=ghs_fake1") {
		t.Fatalf("the allowed repository's path was refused: %q", out)
	}
	if tok, _ := r.fake.calls(); tok != 1 {
		t.Fatalf("%d token calls, want 1 (only the matching request)", tok)
	}
}

func TestTheCredentialHelperDoesNothingForStoreAndEraseAndRefusesOtherWords(t *testing.T) {
	r := newRig(t)
	for _, op := range []string{"store", "erase"} {
		code, out, errs := r.runIn(gitGet+"username=x\npassword=y\n\n", "--perms", "push", "--installation-id", "77", "credential", op)
		if code != 0 || out != "" || errs != "" {
			t.Fatalf("%s: code=%d out=%q err=%q", op, code, out, errs)
		}
	}
	if code, out, _ := r.runIn(gitGet, "--perms", "push", "--installation-id", "77", "credential", "list"); code == 0 || out != "" {
		t.Fatal("an unknown credential operation was accepted")
	}
	if tok, _ := r.fake.calls(); tok != 0 {
		t.Fatal("store or erase reached GitHub")
	}
}

func TestTheCredentialHelperFailsClosedOnABadKeyAndNeverPrintsASecret(t *testing.T) {
	r := newRig(t)
	os.Chmod(r.keyFile(), 0o644)
	code, out, errs := r.runIn(gitGet, "--perms", "push", "--installation-id", "77", "credential", "get")
	if code == 0 || out != "" || strings.Contains(errs, "BEGIN") {
		t.Fatalf("code=%d out=%q err=%q", code, out, errs)
	}
}

// #5528 (Security): an installation on another account is not the organization's, and a credential request for another owner's repository of the same name gets nothing.
func TestAnInstallationOnAnotherAccountIsNotUsed(t *testing.T) {
	r := newRig(t)
	r.fake.account = "someone-else"
	code, out, errs := r.run("--perms", "push", "token")
	if code == 0 || out != "" || !strings.Contains(errs, "no installation") {
		t.Fatalf("code=%d out=%q err=%q", code, out, errs)
	}
	if tokens, _ := r.fake.calls(); tokens != 0 {
		t.Fatal("a token was requested for an installation on another account")
	}
}

func TestACredentialRequestForAnotherOwnersRepositoryGetsNothing(t *testing.T) {
	r := newRig(t)
	for _, path := range []string{"evil/coral.git", "evil/coral", "subgentic-evil/coral.git", "coral.git", "a/subgentic/coral.git"} {
		code, out, _ := r.runIn("protocol=https\nhost=github.com\npath="+path+"\n\n", "--perms", "push", "--installation-id", "77", "credential", "get")
		if code != 0 || out != "" {
			t.Fatalf("%s: code=%d out=%q: a token for it must not be printed", path, code, out)
		}
	}
	if tokens, _ := r.fake.calls(); tokens != 0 {
		t.Fatal("a token was requested for another owner's repository")
	}
	if code, out, _ := r.runIn("protocol=https\nhost=github.com\npath=Subgentic/Coral.git\n\n", "--perms", "push", "--installation-id", "77", "credential", "get"); code != 0 || !strings.Contains(out, "password=ghs_fake1") {
		t.Fatalf("the organization's own repository is answered: code=%d out=%q", code, out)
	}
}
